// ==UserScript==
// @name         NOING 미디어킷 첨부
// ※ @name 에 버전을 넣지 말 것. Tampermonkey 는 이름이 같아야 같은 스크립트로 보고
//   제자리에서 갱신한다. 버전이 들어 있으면 올릴 때마다 새 스크립트로 쌓인다.
// @namespace    http://tampermonkey.net/
// @version      1.16
// @description  네이버 메일에 미디어킷 PDF 를 버튼 한 번으로 첨부합니다
// @match        *://mail.naver.com/*
// @match        *://mail.naver.com/v2/*
// @run-at       document-idle
// @noframes
// @grant        none
// @updateURL    https://sohada2.github.io/noing-mail-43b1f9/noing_attach.user.js
// @downloadURL  https://sohada2.github.io/noing-mail-43b1f9/noing_attach.user.js
// ==/UserScript==

(function () {
  'use strict';
  var VER   = '1.16';        // 스크립트 자체 버전 (자동 업데이트용)
  var MKVER = '1.10';      // 담겨 있는 미디어킷 버전
  var MKDATE = '10/01';    // PDF 를 만든 날짜
  var FNAME = "[\ubbf8\ub514\uc5b4\ud0b7] \uc790\ucde8\uc0dd\uc73c\ub85c \uc0b4\uc544\ub0a8\uae30.pdf";
  var B64   = "";

  function setMsg(txt, color) {
    var b = document.getElementById('noing-att-msg');
    if (b) { b.textContent = txt; b.style.color = color; }
  }

  var DOCS  = [{"name": "노잉커뮤니케이션즈_사업자등록증.pdf", "label": "사업자등록증", "mime": "application/pdf", "b64": "", "kb": 1823}, {"name": "노잉커뮤니케이션즈_통장사본.pdf", "label": "통장사본", "mime": "application/pdf", "b64": "", "kb": 375}];         // 서류 버튼들 (통장사본·사업자등록증 등)

  // ── 새 버전 확인 ────────────────────────────────────────────
  //  version.json 은 몇십 바이트라 메일을 열 때마다 읽어도 부담이 없다.
  var VERSION_URL = 'https://sohada2.github.io/noing-mail-43b1f9/version.json';
  var UPDATE_PAGE = 'https://sohada2.github.io/noing-mail-43b1f9/noing_attach.user.js';      // 열면 Tampermonkey 설치 화면이 뜬다
  var SELF_FILE   = 'noing_attach.user.js';
  var newVer = '', updChecked = false;

  function isNewer(cur, latest) {
    var a = String(cur).split('.'), b = String(latest).split('.');
    for (var i = 0; i < Math.max(a.length, b.length); i++) {
      var x = parseInt(a[i] || '0', 10), y = parseInt(b[i] || '0', 10);
      if (y > x) return true;
      if (y < x) return false;
    }
    return false;
  }
  function fetchLatest(done) {
    if (!VERSION_URL) { done(new Error('no url')); return; }
    try {
      fetch(VERSION_URL + '?t=' + Date.now(), { cache: 'no-store' })
        .then(function (r) { if (!r.ok) throw new Error('http ' + r.status); return r.json(); })
        .then(function (j) { done(null, j[SELF_FILE] || ''); })
        .catch(function (e) { done(e); });
    } catch (e) { done(e); }
  }
  // ── 배지 모양 ──────────────────────────────────────────────
  var ACCENT = '#ffb020';
  function paintNew(el, ver) {
    el.textContent = '';
    var dot = document.createElement('span');
    dot.style.cssText = 'display:inline-block;width:6px;height:6px;border-radius:50%;' +
                        'background:' + ACCENT + ';margin-right:7px;vertical-align:1px';
    var txt = document.createElement('span');
    txt.textContent = '새 버전 v' + ver;
    var act = document.createElement('span');
    act.textContent = '업데이트 ›';
    act.style.cssText = 'color:' + ACCENT + ';margin-left:10px;font-weight:700';
    el.appendChild(dot); el.appendChild(txt); el.appendChild(act);
    el.style.background = '#111111';
    el.style.color = '#ffffff';
    el.style.border = '1px solid rgba(255,176,32,0.5)';
    el.style.borderRadius = '999px';
    el.style.padding = '4px 12px';
    el.style.boxShadow = '0 1px 6px rgba(0,0,0,0.3)';
    el.style.cursor = 'pointer';
  }
  function paintNormal(el, text) {
    el.textContent = text;
    el.style.background = 'rgba(0,0,0,0.75)';
    el.style.color = '#999999';
    el.style.border = 'none';
    el.style.borderRadius = '4px';
    el.style.padding = '3px 10px';
    el.style.boxShadow = 'none';
  }
  function openUpdate() { window.open(UPDATE_PAGE, '_blank'); }
  function startUpdateCheck() {
    if (updChecked) return;
    updChecked = true;
    fetchLatest(function (err, v) {
      if (!err && v && isNewer(VER, v)) { newVer = v; refreshUpdateUI(); }
    });
  }

  function refreshUpdateUI() {
    var m = document.getElementById('noing-att-msg');
    var t = document.getElementById('noing-att-tab');
    if (newVer) {
      if (m) paintNew(m, newVer);
      if (t) {                              // 접힌 알약 : 초록은 그대로 두고 노란 점만 붙인다
        t.textContent = '📎 첨부';
        var d = document.createElement('span');
        d.style.cssText = 'display:inline-block;width:6px;height:6px;border-radius:50%;' +
                          'background:' + ACCENT + ';margin-left:7px;vertical-align:1px';
        t.appendChild(d);
        t.style.opacity = '1';
      }
    } else if (m) {
      paintNormal(m, '미디어킷 v' + MKVER + '  ·  ' + MKDATE + ' 기준');
    }
  }

  function toFile(fname, b64, mime) {
    var bin = atob(b64);
    var buf = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
    return new File([buf], fname, { type: mime || 'application/pdf' });
  }

  // ── 후보 수집 : 아무것도 건드리지 않고 목록만 만든다 ──────
  function collect() {
    var out = [];
    function scan(doc, where) {
      if (!doc) return;
      try {
        doc.querySelectorAll('input[type=file]').forEach(function (n, i) {
          var box = null;
          try { box = n.getBoundingClientRect(); } catch (e) {}
          out.push({
            el: n, where: where,
            id: n.id || '', name: n.name || '',
            cls: (n.className || '').toString().slice(0, 60),
            accept: n.getAttribute('accept') || '',
            multiple: n.multiple,
            files: n.files ? n.files.length : -1,
            near: (function () {
              var p = n.parentElement, t = '';
              for (var k = 0; k < 4 && p; k++) {
                t = (p.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 40);
                if (t) break;
                p = p.parentElement;
              }
              return t;
            })()
          });
        });
      } catch (e) {}
    }
    scan(document, 'page');
    document.querySelectorAll('iframe').forEach(function (fr, i) {
      try { scan(fr.contentDocument || fr.contentWindow.document, 'iframe#' + i); } catch (e) {}
    });
    return out;
  }

  // ── 진단 : 이벤트를 전혀 발생시키지 않는다 ────────────────
  function diagnose(head) {
    head = head || '';
    var list = collect();
    if (!list.length) {
      alert('파일 입력칸을 하나도 찾지 못했습니다.\n\n답장 창을 연 뒤 다시 눌러주세요.');
      return;
    }
    var lines = list.map(function (o, i) {
      return '[' + i + '] ' + o.where
           + '\n    id=' + (o.id || '-')
           + '  name=' + (o.name || '-')
           + '\n    class=' + (o.cls || '-')
           + '\n    accept=' + (o.accept || '-')
           + '  multiple=' + o.multiple
           + '  기존파일=' + o.files
           + '\n    주변글자=' + (o.near || '-');
    });
    var txt = head + '파일 입력칸 ' + list.length + '개를 찾았습니다.\n\n' + lines.join('\n\n');
    try {
      navigator.clipboard.writeText(txt);
      setMsg('진단 결과 복사됨', '#8ce8a0');
    } catch (e) {}
    console.log(txt);
    alert(txt + '\n\n(클립보드에도 복사했습니다. 그대로 붙여넣어 주세요.)');
  }

  // ── 대상 선택 ─────────────────────────────────────────────
  //  실제 네이버 메일 확인 결과 (2026.8)
  //    [0] id=ATTACH_LOCAL_FILE_ELEMENT_ID  "내 PC에서 업로드"  ← 첨부칸
  //    [1] id 없음                          "내게쓰기"          ← 건드리면 발송됨
  //  두 칸 모두 multiple=true / accept 없음 이라 속성만으로는 구분되지 않는다.
  var EXACT_ID = 'ATTACH_LOCAL_FILE_ELEMENT_ID';
  var BAN = /내게쓰기|내게쓴|메일함/;

  function pick(list) {
    // 1순위 : 확인된 첨부칸 ID
    for (var i = 0; i < list.length; i++) {
      if (list[i].id === EXACT_ID) return { t: list[i], sure: true };
    }
    // 2순위 : ID 에 ATTACH 가 들어간 칸 (네이버가 ID 를 바꾼 경우)
    for (var i = 0; i < list.length; i++) {
      if (/attach/i.test(list[i].id) && !BAN.test(list[i].near)) {
        return { t: list[i], sure: false };
      }
    }
    // 3순위 : 주변 글자에 업로드·첨부가 있고 금지어가 없는 칸
    for (var i = 0; i < list.length; i++) {
      if (/업로드|첨부/.test(list[i].near) && !BAN.test(list[i].near)) {
        return { t: list[i], sure: false };
      }
    }
    return null;
  }

  function attach(fname, b64, mime, label) {
    fname = fname || FNAME;
    b64   = b64   || B64;
    mime  = mime  || 'application/pdf';
    label = label || ('미디어킷 v' + MKVER);
    var list = collect();
    if (!list.length) {
      alert('파일 첨부칸을 찾지 못했습니다.\n\n답장(또는 편지쓰기) 창을 먼저 열어주세요.');
      return;
    }
    var r = pick(list);
    if (!r) {
      setMsg('대상 못 찾음', '#ffb0b0');
      // 안전을 위해 아무것도 건드리지 않고 원인 정보를 보여준다
      diagnose('첨부칸을 특정하지 못해 아무것도 건드리지 않았습니다.\n'
             + '아래 내용을 그대로 보내주시면 맞춰 드리겠습니다.\n\n');
      return;
    }
    // 확인된 칸이 아니면 반드시 물어본다
    if (!r.sure) {
      if (!confirm('확인된 첨부칸을 찾지 못해 아래 칸으로 시도합니다.\n\n'
                 + 'id : ' + (r.t.id || '-') + '\n'
                 + '주변 : ' + (r.t.near || '-') + '\n\n'
                 + '진행할까요?')) { setMsg('취소됨', '#999999'); return; }
    }

    try {
      var inp = r.t.el, dt = new DataTransfer();
      if (inp.files) {
        for (var i = 0; i < inp.files.length; i++) dt.items.add(inp.files[i]);
      }
      dt.items.add(toFile(fname, b64, mime));
      inp.files = dt.files;
      inp.dispatchEvent(new Event('change', { bubbles: true }));   // change 만
      setMsg(label + ' 첨부 완료 — 목록 확인', '#8ce8a0');
      setTimeout(function () {
        refreshUpdateUI();
      }, 6000);
    } catch (e) {
      setMsg('첨부 실패', '#ffb0b0');
      alert('첨부 중 오류: ' + e.message);
    }
  }

  function makeBtn(label, bg, onClick, small) {
    var b = document.createElement('button');
    b.textContent = label;
    b.style.cssText = [
      small ? 'padding:5px 9px' : 'padding:7px 12px',
      'border:none', 'border-radius:6px',
      'background:' + bg, 'color:#fff',
      small ? 'font-size:11px' : 'font-size:12px', 'font-weight:700',
      'cursor:pointer', 'box-shadow:0 1px 5px rgba(0,0,0,0.22)',
      'font-family:Apple SD Gothic Neo,Malgun Gothic,sans-serif',
      'white-space:nowrap', 'line-height:1.3'
    ].join(';');
    b.addEventListener('mouseover', function () { b.style.opacity = '0.85'; });
    b.addEventListener('mouseout',  function () { b.style.opacity = '1'; });
    b.addEventListener('click', onClick);
    return b;
  }

  function addPanel() {
    if (document.getElementById('noing-att')) return;
    if (!document.body) return;

    // 평소엔 작은 알약 하나만 보이고, 마우스를 올리면 펼친다.
    // 메일 목록을 가리지 않게 하려는 것이다.
    var p = document.createElement('div');
    p.id = 'noing-att';
    p.style.cssText = [
      'position:fixed', 'bottom:16px', 'left:16px', 'z-index:2147483646',
      'display:flex', 'flex-direction:column', 'gap:4px',
      'align-items:flex-start'
    ].join(';');

    // 접혔을 때 보이는 손잡이
    var tab = document.createElement('div');
    tab.id = 'noing-att-tab';
    tab.textContent = '📎 첨부';
    tab.style.cssText = [
      'padding:5px 11px', 'border-radius:14px', 'background:#1f6f43',
      'color:#ffffff', 'font-size:11px', 'font-weight:700', 'cursor:pointer',
      'font-family:Apple SD Gothic Neo,Malgun Gothic,sans-serif',
      'box-shadow:0 1px 5px rgba(0,0,0,0.25)', 'white-space:nowrap',
      'user-select:none', 'opacity:0.75'
    ].join(';');

    // 펼쳤을 때 나오는 알맹이
    var box = document.createElement('div');
    box.style.cssText = [
      'display:none', 'flex-direction:column', 'gap:4px',
      'align-items:flex-start'
    ].join(';');

    var badge = document.createElement('div');
    badge.id = 'noing-att-msg';
    badge.textContent = '미디어킷 v' + MKVER + '  ·  ' + MKDATE + ' 기준';
    badge.style.cssText = [
      'padding:2px 8px', 'border-radius:4px', 'background:rgba(0,0,0,0.75)',
      'color:#999999', 'font-size:10px', 'font-weight:700',
      'font-family:Apple SD Gothic Neo,Malgun Gothic,sans-serif',
      'white-space:nowrap', 'user-select:none'
    ].join(';');
    box.appendChild(badge);
    box.appendChild(makeBtn('📎 미디어킷 v' + MKVER, '#1f6f43',
                            function () { attach(); }));

    // 서류 버튼 — 서류/ 폴더에 넣은 파일마다 하나씩
    if (DOCS.length) {
      var row = document.createElement('div');
      row.style.cssText = 'display:flex;gap:4px;flex-wrap:wrap';
      DOCS.forEach(function (d) {
        row.appendChild(makeBtn('📄 ' + d.label, '#3d4c5c', function () {
          attach(d.name, d.b64, d.mime, d.label);
        }, true));
      });
      box.appendChild(row);
    }

    // 펼치기 / 접기 — 마우스만 올리면 열린다 (클릭 한 번 더 안 해도 되게)
    var timer = null, pinned = false;
    function open() {
      if (timer) { clearTimeout(timer); timer = null; }
      box.style.display = 'flex';
      tab.style.display = 'none';
    }
    function close() {
      if (pinned) return;
      box.style.display = 'none';
      tab.style.display = '';
    }
    p.addEventListener('mouseenter', open);
    p.addEventListener('mouseleave', function () {
      if (timer) clearTimeout(timer);
      timer = setTimeout(close, 400);      // 살짝 벗어나도 바로 닫히지 않게
    });
    // 손잡이를 누르면 계속 열어 둔다 (다시 누르면 해제)
    tab.addEventListener('click', function () { pinned = true; open(); });
    badge.addEventListener('click', function () {
      if (newVer) { openUpdate(); return; }          // 새 버전이 있으면 설치 화면
      pinned = !pinned; if (!pinned) close();
    });

    p.appendChild(tab);
    p.appendChild(box);
    document.body.appendChild(p);
    startUpdateCheck();
  }

  addPanel();
  setTimeout(addPanel, 1000);
  setTimeout(addPanel, 3000);
  new MutationObserver(addPanel)
    .observe(document.documentElement, { childList: true, subtree: false });
})();
